export function getShopifyIds(sku) {
  if (!sku) return null;
  const rawKey = String(sku).toLowerCase().trim();
  const sanitizedKey = rawKey.replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return SHOPIFY_ID_MAP[sanitizedKey] || SHOPIFY_ID_MAP[rawKey] || null;
}
